import { fireEvent, screen, within } from "@testing-library/react";
import { beforeEach, describe, expect, it, vi } from "vitest";
import { renderWithProviders } from "../tests/utils";
import {
  ConversationEventType,
  UtteranceType,
  type Conversation,
  type ConversationEvent,
} from "../types";
import { ConversationSession } from "./ConversationSession";

// Mock child components to isolate ConversationSession. Event stays real so
// the grouping tests exercise the actual tool-call header and toggle.
vi.mock("./ConversationLog/Message/Message", () => ({
  Message: ({ utterance, ...props }: Record<string, unknown>) => (
    <div
      data-testid="message"
      data-utterance={JSON.stringify(utterance)}
      data-props={JSON.stringify(props)}
    />
  ),
}));
vi.mock("./ConversationLoadingSpinner", () => ({
  ConversationLoadingSpinner: () => <div data-testid="spinner"></div>,
}));

function lifecycleEvent(
  id: string,
  eventType: ConversationEventType,
  skillId: string,
): ConversationEvent {
  return {
    __typename: "ConversationEvent",
    id,
    conversationEventType: eventType,
    skillId,
    flowId: skillId,
    metadata: { parseData: undefined },
    timestamp: "2026-08-25T00:00:00.000Z",
    originalTimestamp: 0,
  };
}

describe("ConversationSession", () => {
  let baseConversation: Conversation;

  beforeEach(() => {
    baseConversation = {
      id: "conv1",
      startDate: new Date().toISOString(),
      events: [
        {
          id: "1",
          type: UtteranceType.User,
          text: "Hello",
        },
        {
          id: "2",
          type: UtteranceType.Bot,
          text: "Hi there!",
        },
      ],
      // ...other props as required
    } as Conversation;
  });

  it("renders session start date label", () => {
    renderWithProviders(
      <ConversationSession conversation={baseConversation} inspectorMode={false} />,
    );
    expect(screen.getByText(/Session started on/)).toBeInTheDocument();
  });

  it("renders Message components for user and bot utterances", () => {
    renderWithProviders(
      <ConversationSession conversation={baseConversation} inspectorMode={false} />,
    );
    const messages = screen.getAllByTestId("message");
    expect(messages).toHaveLength(2);
    expect(messages[0]).toHaveAttribute("data-utterance", expect.stringContaining("Hello"));
    expect(messages[1]).toHaveAttribute("data-utterance", expect.stringContaining("Hi there!"));
  });

  it("marks Message as interactive only for the last bot utterance", () => {
    renderWithProviders(
      <ConversationSession
        conversation={baseConversation}
        inspectorMode={false}
        interactive={true}
      />,
    );
    const messages = screen.getAllByTestId("message");
    expect(messages[1].dataset.props).toContain('"isInteractive":true');
    expect(messages[0].dataset.props).not.toContain('"isInteractive":true');
  });

  it("renders ConversationLoadingSpinner if waitingForResponse", () => {
    renderWithProviders(
      <ConversationSession
        conversation={baseConversation}
        inspectorMode={false}
        waitingForResponse
      />,
    );
    expect(screen.getByTestId("spinner")).toBeVisible();
  });

  it("highlights selected message/event by selectedElementId", () => {
    renderWithProviders(
      <ConversationSession
        conversation={baseConversation}
        inspectorMode={true}
        selectedElementId="2"
        selectable
      />,
    );
    const messages = screen.getAllByTestId("message");
    expect(messages[1].dataset.props).toContain('"isSelected":true');
  });

  it("renders session end date label when endDate is provided", () => {
    const conversationWithEndDate = {
      ...baseConversation,
      endDate: new Date("2024-06-15T10:30:00.000Z").toISOString(),
    };
    renderWithProviders(
      <ConversationSession conversation={conversationWithEndDate} inspectorMode={false} />,
    );
    expect(screen.getByText(/Session ended on/)).toBeInTheDocument();
  });

  it("does not render session end date label when endDate is not provided", () => {
    renderWithProviders(
      <ConversationSession conversation={baseConversation} inspectorMode={false} />,
    );
    expect(screen.queryByText(/Session ended on/)).not.toBeInTheDocument();
  });

  it("renders Skill* rows in skill mode", () => {
    baseConversation.events = [
      lifecycleEvent("skill", ConversationEventType.SkillActivated, "card_replace"),
    ];

    renderWithProviders(
      <ConversationSession conversation={baseConversation} inspectorMode={true} />,
      { initialStoreState: { engineType: "mantle", skillCatalog: {} } },
    );

    const rows = screen.getAllByTestId("conversation-events");
    const text = rows.map((element) => element.textContent ?? "").join(" ");
    expect(text).toContain("skill activated");
  });

  it("renders CALM v1 flow rows outside skill mode", () => {
    baseConversation.events = [
      lifecycleEvent("flow", ConversationEventType.FlowStarted, "card_replace"),
    ];

    renderWithProviders(
      <ConversationSession conversation={baseConversation} inspectorMode={true} />,
    );

    const rows = screen.getAllByTestId("conversation-events");
    const text = rows.map((element) => element.textContent ?? "").join(" ");
    expect(text).toContain("started");
  });

  describe("tool-call grouping", () => {
    const skillModeState = { engineType: "mantle" as const, skillCatalog: {} };

    function conversationEvent(
      id: string,
      type: ConversationEventType,
      overrides: Partial<ConversationEvent> = {},
    ): ConversationEvent {
      return {
        id,
        conversationEventType: type,
        name: "",
        actionText: "",
        flowId: "",
        stepId: "",
        slotValue: null,
        timestamp: "2020-01-01T00:00:00.000Z",
        originalTimestamp: 0,
        metadata: { parseData: {} },
        __typename: "ConversationEvent",
        ...overrides,
      };
    }

    function toolCallConversation(): Conversation {
      return {
        id: "conv-tool",
        startDate: new Date().toISOString(),
        events: [
          conversationEvent("call", ConversationEventType.ToolExecuted, {
            originalTimestamp: 1000,
            metadata: { parseData: {}, tool_name: "lock_card", tool_call_id: "c1" },
          }),
          conversationEvent("write", ConversationEventType.MemorySet, {
            name: "card_replace.replacement_reason",
            value: "lost",
            originalTimestamp: 1001,
            metadata: {
              parseData: {},
              mantle_write_provenance: { tool: "lock_card", position: 1, tool_call_id: "c1" },
            },
          }),
        ],
      } as Conversation;
    }

    it("collapses a tool call's memory writes behind a toggle in skill mode", () => {
      renderWithProviders(
        <ConversationSession conversation={toolCallConversation()} inspectorMode={true} />,
        { initialStoreState: skillModeState },
      );

      expect(screen.getByText(/Tool call:/)).toBeInTheDocument();
      expect(screen.getByText("lock_card")).toBeInTheDocument();
      expect(screen.queryByTestId("tool-call-group")).not.toBeInTheDocument();
      expect(screen.queryByText("replacement_reason")).not.toBeInTheDocument();

      fireEvent.click(screen.getByTestId("tool-call-toggle"));
      const group = screen.getByTestId("tool-call-group");
      expect(within(group).getByText("replacement_reason")).toBeInTheDocument();
      expect(within(group).getByText(/set to/)).toBeInTheDocument();

      fireEvent.click(screen.getByTestId("tool-call-toggle"));
      expect(screen.queryByTestId("tool-call-group")).not.toBeInTheDocument();
      expect(screen.queryByText("replacement_reason")).not.toBeInTheDocument();
    });

    it("keeps a group expanded across a tracker re-render", () => {
      const { rerender } = renderWithProviders(
        <ConversationSession conversation={toolCallConversation()} inspectorMode={true} />,
        { initialStoreState: skillModeState },
      );

      fireEvent.click(screen.getByTestId("tool-call-toggle"));
      expect(screen.getByTestId("tool-call-group")).toBeInTheDocument();

      // A tracker frame re-maps the same raw events. Event ids are deterministic
      // (derived from position and timestamp), so the fresh mapping produces the
      // same call id and expansion keyed on it survives.
      rerender(<ConversationSession conversation={toolCallConversation()} inspectorMode={true} />);

      expect(screen.getByTestId("tool-call-group")).toBeInTheDocument();
    });

    it("renders the same events flat without a toggle outside skill mode", () => {
      renderWithProviders(
        <ConversationSession conversation={toolCallConversation()} inspectorMode={true} />,
      );

      expect(screen.getByText("lock_card")).toBeInTheDocument();
      expect(screen.queryByTestId("tool-call-toggle")).not.toBeInTheDocument();
      expect(screen.queryByTestId("tool-call-group")).not.toBeInTheDocument();
      expect(screen.getByText("replacement_reason")).toBeInTheDocument();
    });
  });

  it("renders OrderedBlock* rows in skill mode", () => {
    baseConversation.events = [
      {
        ...lifecycleEvent("block", ConversationEventType.OrderedBlockEntered, "travel_notice"),
        blockId: "submit",
      },
    ];

    renderWithProviders(
      <ConversationSession conversation={baseConversation} inspectorMode={true} />,
      { initialStoreState: { engineType: "mantle", skillCatalog: {} } },
    );

    const rows = screen.getAllByTestId("conversation-events");
    const text = rows.map((element) => element.textContent ?? "").join(" ");
    expect(text).toContain("block entered");
  });

  it("groups only MemorySet writes under a tool call in skill mode", () => {
    // A Mantle group's children come from MemorySet events.
    baseConversation.events = [
      {
        id: "call",
        conversationEventType: ConversationEventType.ToolExecuted,
        name: "",
        actionText: "",
        flowId: "",
        stepId: "",
        slotValue: null,
        timestamp: "2020-01-01T00:00:00.000Z",
        originalTimestamp: 1000,
        metadata: { parseData: {}, tool_name: "lock_card", tool_call_id: "c1" },
        __typename: "ConversationEvent",
      },
      {
        id: "write",
        conversationEventType: ConversationEventType.MemorySet,
        name: "card_replace.replacement_reason",
        actionText: "",
        flowId: "",
        stepId: "",
        value: "lost",
        timestamp: "2020-01-01T00:00:01.000Z",
        originalTimestamp: 1001,
        metadata: {
          parseData: {},
          mantle_write_provenance: { tool: "lock_card", position: 1, tool_call_id: "c1" },
        },
        __typename: "ConversationEvent",
      },
    ] as ConversationEvent[];

    renderWithProviders(
      <ConversationSession conversation={baseConversation} inspectorMode={true} />,
      { initialStoreState: { engineType: "mantle", skillCatalog: {} } },
    );

    fireEvent.click(screen.getByTestId("tool-call-toggle"));
    const group = screen.getByTestId("tool-call-group");
    expect(within(group).getByText("replacement_reason")).toBeInTheDocument();
    expect(within(group).getByText(/set to/)).toBeInTheDocument();
    expect(within(group).queryByText(/Slots reset/)).not.toBeInTheDocument();
  });
});
